({__plugin:null,__load(){if(this.__plugin)return this.__plugin;this.__plugin=function(){"use strict";let locales=unbound.i18n.createLocales({FRIEND:"Friend"}),messages=locales.messages;function withFriendLabel(tags,label){var text=tags.opTagText?`${tags.opTagText} \xb7 ${label}`:label;return{...tags,opTagText:text,tagAccessibilityLabel:tags.tagAccessibilityLabel??text}}function patchTagProperties(){var TagProperties=unbound.metro.findByName("getTagProperties",{interop:!1}),Relationships=unbound.flux.getStore("Relationship");TagProperties&&"function"==typeof Relationships?.isFriend?unbound.patcher.after(TagProperties,"default",({args,result})=>{var author=args[0]?.message?.author?.id;if(result&&author&&Relationships.isFriend(author))return withFriendLabel(result,messages.FRIEND)}):logger.warn("Friend markers skipped: Discord moved getTagProperties or RelationshipStore.")}return locales.format,locales.useMessages,{start:function start(){patchTagProperties()},stop:function stop(){unbound.patcher.unpatchAll()}}}();return this.__plugin;}})